   showStep(step) {
     for (const stepName of STEPS) {
@@ -178,5 +232,14 @@ export const qrExportPane = {
     );
     this.updateCodesState();
     this.showStep("Codes");
+    this.populateSummary(accountKeys, includePasswords, wizard.getTotalSteps());
